16	export async function requireAdmin() {
17	  const auth = await getAuthenticatedUser()
18	  if (!auth) {
19	    throw new ActionError('UNAUTHENTICATED', 'Sign in required')
20	  }
21	  if (!['admin', 'super_admin'].includes(auth.user.role)) {
22	    throw new ActionError('FORBIDDEN', 'Admin access required')
23	  }
24	  return auth
25	}
