27	export async function requireSuperAdmin() {
28	  const auth = await getAuthenticatedUser()
29	  if (!auth) {
30	    throw new ActionError('UNAUTHENTICATED', 'Sign in required')
31	  }
32	  if (auth.user.role !== 'super_admin') {
33	    throw new ActionError('FORBIDDEN', 'Super admin access required')
34	  }
35	  return auth
36	}
