3	import { z } from 'zod'
4	import { createServiceRoleClient, createServiceRoleClientRaw } from '@/lib/supabase/server'
5	import { requireSuperAdmin, ActionError, type ActionResult } from './_guard'
6	import { revalidatePath } from 'next/cache'
7	
8	const grantCreditsSchema = z.object({
9	  userId: z.string().uuid(),
10	  amount: z.number().int().min(1).max(1000),
11	  reason: z.string().min(5).max(500),
12	})
13	
14	export async function grantScanCredits(
15	  input: z.infer<typeof grantCreditsSchema>,
16	): Promise<ActionResult<{ newLimit: number }>> {
17	  try {
18	    const admin = await requireSuperAdmin()
19	
20	    const parsed = grantCreditsSchema.safeParse(input)
21	    if (!parsed.success) {
22	      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
23	    }
24	
25	    const { userId, amount, reason } = parsed.data
26	    const srTyped = createServiceRoleClient()
27	    const srRaw = createServiceRoleClientRaw()
28	
29	    // Direct update approach (no custom RPC needed)
30	    const { data: profileData, error: fetchErr } = await srTyped
31	      .from('profiles')
32	      .select('*')
33	      .eq('id', userId)
34	      .single()
35	
36	    if (fetchErr || !profileData) {
37	      return { ok: false, error: 'User not found', code: 'NOT_FOUND' }
38	    }
39	
40	    const currentProfile = profileData as { scan_limit: number }
41	    const newLimit = currentProfile.scan_limit + amount
42	
43	    const { error: setErr } = await srRaw
44	      .from('profiles')
45	      .update({ scan_limit: newLimit })
46	      .eq('id', userId)
47	
48	    if (setErr) {
49	      return { ok: false, error: 'Failed to update scan limit', code: 'DB_ERROR' }
50	    }
51	
52	    await srRaw.from('audit_logs').insert({
53	      admin_id: admin.user.id,
54	      action: 'credits.grant',
55	      target_type: 'user',
56	      target_id: userId,
57	      metadata: { amount, reason, new_limit: newLimit },
58	    })
59	
60	    revalidatePath(`/admin/users/${userId}`)
61	    return { ok: true, data: { newLimit } }
62	  } catch (err) {
63	    if (err instanceof ActionError) {
64	      return { ok: false, error: err.message, code: err.code }
65	    }
66	    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
67	  }
68	}
