3	import { z } from 'zod'
4	import { createServiceRoleClient, createServiceRoleClientRaw } from '@/lib/supabase/server'
5	import { requireAdmin, ActionError, type ActionResult } from './_guard'
6	import { revalidatePath } from 'next/cache'
7	
8	const requeueStuckSchema = z.object({
9	  olderThanMinutes: z.number().int().min(5).max(1440).default(15),
10	})
11	
12	export async function requeueStuckScans(
13	  input: z.infer<typeof requeueStuckSchema> = { olderThanMinutes: 15 },
14	): Promise<ActionResult<{ count: number; scanIds: string[] }>> {
15	  try {
16	    const admin = await requireAdmin()
17	
18	    const parsed = requeueStuckSchema.safeParse(input)
19	    if (!parsed.success) {
20	      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
21	    }
22	
23	    const { olderThanMinutes } = parsed.data
24	    const cutoff = new Date(Date.now() - olderThanMinutes * 60 * 1000).toISOString()
25	
26	    const srTyped = createServiceRoleClient()
27	    const srRaw = createServiceRoleClientRaw()
28	
29	    // Find stuck scans (limit 50)
30	    const { data: stuckScansRaw, error: fetchErr } = await srTyped
31	      .from('scans')
32	      .select('*')
33	      .eq('status', 'analyzing')
34	      .lt('created_at', cutoff)
35	      .limit(50)
36	
37	    if (fetchErr) {
38	      return { ok: false, error: 'Failed to fetch stuck scans', code: 'DB_ERROR' }
39	    }
40	
41	    if (!stuckScansRaw || stuckScansRaw.length === 0) {
42	      return { ok: true, data: { count: 0, scanIds: [] } }
43	    }
44	
45	    const stuckScans = stuckScansRaw as Array<{ id: string }>
46	    const scanIds = stuckScans.map((s) => s.id)
47	
48	    const { error: updateErr } = await srRaw
49	      .from('scans')
50	      .update({ status: 'pending', error_message: null })
51	      .in('id', scanIds)
52	
53	    if (updateErr) {
54	      return { ok: false, error: 'Failed to requeue scans', code: 'DB_ERROR' }
55	    }
56	
57	    await srRaw.from('audit_logs').insert({
58	      admin_id: admin.user.id,
59	      action: 'queue.requeue_bulk',
60	      target_type: null,
61	      target_id: null,
62	      metadata: { count: scanIds.length, scan_ids: scanIds, threshold_minutes: olderThanMinutes },
63	    })
64	
65	    revalidatePath('/admin/system')
66	    return { ok: true, data: { count: scanIds.length, scanIds } }
67	  } catch (err) {
68	    if (err instanceof ActionError) {
69	      return { ok: false, error: err.message, code: err.code }
70	    }
71	    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
72	  }
73	}
