3	import { z } from 'zod'
4	import { createClient, createServiceRoleClientRaw } from '@/lib/supabase/server'
5	import { requireSuperAdmin, ActionError, type ActionResult } from './_guard'
6	import { revalidatePath } from 'next/cache'
7	
8	const resolveErrorSchema = z.object({
9	  errorId: z.string().uuid(),
10	  note: z.string().min(3).max(1000),
11	})
12	
13	export async function resolveErrorLog(
14	  input: z.infer<typeof resolveErrorSchema>,
15	): Promise<ActionResult<void>> {
16	  try {
17	    const admin = await requireSuperAdmin()
18	
19	    const parsed = resolveErrorSchema.safeParse(input)
20	    if (!parsed.success) {
21	      return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input', code: 'VALIDATION_ERROR' }
22	    }
23	
24	    const { errorId, note } = parsed.data
25	
26	    // Use session client for error_log update — RLS policy error_log_super_admin_update enforces role
27	    const supabase = await createClient()
28	    const srRaw = createServiceRoleClientRaw()
29	
30	    const { error } = await (supabase as ReturnType<typeof createServiceRoleClientRaw>)
31	      .from('admin_error_log')
32	      .update({
33	        resolved: true,
34	        resolved_at: new Date().toISOString(),
35	        resolved_by: admin.user.id,
36	        resolution_note: note,
37	      })
38	      .eq('id', errorId)
39	      .eq('resolved', false)
40	
41	    if (error) {
42	      return { ok: false, error: 'Failed to resolve error log', code: 'DB_ERROR' }
43	    }
44	
45	    // Write audit log via service role
46	    await srRaw.from('audit_logs').insert({
47	      admin_id: admin.user.id,
48	      action: 'errorlog.resolve',
49	      target_type: 'error_log',
50	      target_id: errorId,
51	      metadata: { note },
52	    })
53	
54	    revalidatePath('/admin/errors')
55	    return { ok: true, data: undefined }
56	  } catch (err) {
57	    if (err instanceof ActionError) {
58	      return { ok: false, error: err.message, code: err.code }
59	    }
60	    return { ok: false, error: 'Internal server error', code: 'INTERNAL_ERROR' }
61	  }
62	}
