3	import { Component, type ErrorInfo, type ReactNode } from 'react'
4	import { AlertTriangle, RefreshCw } from 'lucide-react'
5	import { Button } from '@/components/ui/button'
6	import { logClientError } from '@/lib/errors/log-client'
7	
8	interface Props {
9	  children: ReactNode
10	  fallback?: ReactNode
11	}
12	
13	interface State {
14	  hasError: boolean
15	  errorMessage: string | null
16	}
17	
18	export class ErrorBoundary extends Component<Props, State> {
19	  state: State = { hasError: false, errorMessage: null }
20	
21	  static getDerivedStateFromError(error: Error): State {
22	    return { hasError: true, errorMessage: error.message }
23	  }
24	
25	  componentDidCatch(error: Error, info: ErrorInfo) {
26	    logClientError(error, {
27	      route: typeof window !== 'undefined' ? window.location.pathname : undefined,
28	      metadata: { componentStack: info.componentStack ?? undefined },
29	    })
30	  }
31	
32	  handleReset = () => {
33	    this.setState({ hasError: false, errorMessage: null })
34	  }
35	
36	  render() {
37	    if (this.state.hasError) {
38	      if (this.props.fallback) return this.props.fallback
39	
40	      return (
41	        <div className="flex flex-col items-center justify-center gap-3 py-12 text-center">
42	          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10">
43	            <AlertTriangle className="h-6 w-6 text-destructive" />
44	          </div>
45	          <div className="space-y-1">
46	            <p className="text-sm font-medium text-foreground">Something went wrong</p>
47	            {this.state.errorMessage && (
48	              <p className="text-xs text-muted-foreground font-mono max-w-xs truncate">
49	                {this.state.errorMessage}
50	              </p>
51	            )}
52	          </div>
53	          <Button size="sm" variant="outline" onClick={this.handleReset}>
54	            <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
55	            Try again
56	          </Button>
57	        </div>
58	      )
59	    }
60	
61	    return this.props.children
62	  }
63	}
