9	}) {
10	  const auth = await getAuthenticatedUser()
11	
12	  if (!auth) {
13	    redirect("/login")
14	  }
15	
16	  const role = auth.user.role
17	  if (role !== "admin" && role !== "super_admin") {
18	    redirect("/dashboard")
19	  }
20	
21	  return <AdminLayout>{children}</AdminLayout>
